let recaptchaLoaded = false;
let siteKey = "";

function loadRecaptchaScript(callback) {
  if (recaptchaLoaded) {
    if (typeof callback === "function") callback();
    return;
  }

  if (!siteKey || siteKey === "") {
    if (typeof callback === "function") callback();
    return;
  }

  const script = document.createElement("script");
  script.src = `https://www.google.com/recaptcha/api.js?render=${siteKey}`;
  script.defer = true;
  script.onload = () => {
    recaptchaLoaded = true;
    if (typeof callback === "function") callback();
  };
  document.head.appendChild(script);
}

if (typeof history !== "undefined" && "scrollRestoration" in history) {
  history.scrollRestoration = "manual";
}

document.addEventListener("DOMContentLoaded", () => {
  if (document.body.classList.contains("editor-preview")) return;

  const footerBanner = document.querySelector(".footer_banner");
  const headNav = document.querySelector(".siteHeader");
  const pageTop = document.querySelector(".pagetop");
  const fadeElements = document.querySelectorAll(".fadein");
  let lastScrollTop = 0;
  let isAnimationReady = false;
  const HIDE_CLASS = "hide";
  let scrollTimeout = null;

  const observer = new IntersectionObserver(
    (entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          entry.target.classList.add("scrollin");
          observer.unobserve(entry.target);
        }
      });
    },
    { threshold: 0.1 }
  );

  fadeElements.forEach((el) => observer.observe(el));

  requestAnimationFrame(() => {
    fadeElements.forEach((el) => el.classList.add("animation-ready"));
    isAnimationReady = true;
  });

  let ticking = false;
  window.addEventListener("scroll", () => {
    if (!isAnimationReady) {
      fadeElements.forEach((el) => el.classList.add("animation-ready"));
      isAnimationReady = true;
    }

    if (scrollTimeout) {
      clearTimeout(scrollTimeout);
    }
    scrollTimeout = setTimeout(() => {
      footerBanner.classList.remove(HIDE_CLASS);
    }, 500);

    if (!ticking) {
      window.requestAnimationFrame(() => {
        const scrollTop =
          window.pageYOffset || document.documentElement.scrollTop;
        if (scrollTop < lastScrollTop) {
          footerBanner.classList.add(HIDE_CLASS);
        } else {
          footerBanner.classList.remove(HIDE_CLASS);
        }
        lastScrollTop = scrollTop;

        pageTop.style.display = scrollTop > 120 ? "block" : "none";

        ticking = false;
      });
      ticking = true;
    }
  });

  if (headNav) {
    headNav.classList.add("fixed");
    headNav.style.top = "0";
  }

  const hamburger = document.querySelector(".siteHeader__hamburger");
  const nav = document.querySelector(".siteHeader__nav");
  if (hamburger && headNav && nav) {
    const updateHamburger = (open) => {
      headNav.classList.toggle("is-open", open);
      hamburger.setAttribute("aria-expanded", open ? "true" : "false");
      hamburger.setAttribute(
        "aria-label",
        open ? "メニューを閉じる" : "メニューを開く"
      );
      const icon = hamburger.querySelector("i");
      if (icon)
        icon.className = open ? "fa-solid fa-times" : "fa-solid fa-bars";
      document.body.style.overflow = open ? "hidden" : "";
    };
    hamburger.addEventListener("click", () =>
      updateHamburger(!headNav.classList.contains("is-open"))
    );
    nav.querySelectorAll("a").forEach((a) => {
      a.addEventListener("click", () => updateHamburger(false));
    });
    window.addEventListener("resize", () => {
      if (window.innerWidth > 768) updateHamburger(false);
    });
    document.addEventListener("keydown", (e) => {
      if (e.key === "Escape" && headNav.classList.contains("is-open"))
        updateHamburger(false);
    });
  }

  pageTop.style.display = "none";

  pageTop.addEventListener("click", (e) => {
    e.preventDefault();
    window.scrollTo({ top: 0, behavior: "smooth" });
  });

  const scrollToHashTarget = (id) => {
    if (!id) return;
    const el = document.getElementById(id);
    if (el) el.scrollIntoView({ behavior: "smooth", block: "center" });
  };
  if (window.location.hash) {
    requestAnimationFrame(() => {
      scrollToHashTarget(window.location.hash.slice(1));
    });
  }
  document.addEventListener("click", (e) => {
    const link = e.target.closest('a[href^="#"]');
    if (!link) return;
    const href = link.getAttribute("href");
    if (!href || href === "#") return;
    const id = href.slice(1);
    if (!id) return;
    if (document.getElementById(id)) {
      e.preventDefault();
      scrollToHashTarget(id);
    }
  });

});
